 * `updated_at` — so a move is a status change plus a touch.
 */
export async function moveIssue(
  actor: Actor,
  input: MoveIssueInput,
): Promise<Issue> {
  return changeIssueStatus(actor, {
    orgId: input.orgId,
    issueId: input.issueId,
    status: input.toStatus,
  });
}

export async function getIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueWithRelations> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const labels = await labelRepo.listLabelsForIssues(orgId, [issue.id]);

  return {
    issue,
    labels: labels[issue.id] ?? [],
    commentCount: await commentRepo.countComments(orgId, issue.id),
    attachmentCount: (await attachmentRepo.listAttachments(orgId, issue.id))
      .length,
  };
}

export async function listIssues(
  actor: Actor,
  input: IssueFilterInput,
): Promise<Page<Issue>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "issue:read", orgResource(input.orgId));
  if (input.projectId !== undefined) {
    const project = await projectRepo.findProjectById(input.orgId, input.projectId);
    if (project) await assertProjectVisible(actor, project);
    return issueRepo.listIssues(input);
  }
  const page = await issueRepo.listIssues(input);
  const projects = await Promise.all([...new Set(page.items.map((issue) => issue.projectId))].map(async (id) => [id, await projectRepo.findProjectById(input.orgId, id)] as const));
  const visibleIds = new Set(await Promise.all(projects.filter((entry) => entry[1] !== null).map(async ([id, project]) => project && await canViewProject(actor, project) ? id : null)).then((ids) => ids.filter((id): id is ProjectId => id !== null)));
  const items = page.items.filter((issue) => visibleIds.has(issue.projectId));
  return { items, nextCursor: items.length < input.limit ? null : page.nextCursor, total: items.length < input.limit ? items.length : page.total };
}

